1	/**
2	 * 额外事件集 — 新增15个高重复价值事件
3	 *
4	 * 设计原则（1.4标准）：
5	 * - 逻辑自洽：事件原因→经过→结果符合现实逻辑
6	 * - 系统联动：每个事件至少影响2个游戏子系统
7	 * - 玩家可感知：通过UI和消息系统自然呈现
8	 * - 重复价值：季节循环事件每年可重复，NPC偶遇依赖好感度变化
9	 *
10	 * 这些事件会被推入 RANDOM_EVENTS 数组，自动参与事件轮询。
11	 * 在 index.html 中 events.js 加载后加载。
12	 */
13	
14	(function () {
15	  if (typeof RANDOM_EVENTS === "undefined") return;
16	
17	  var EXTRA_EVENTS = [
18	    // ============================================================
19	    // 城市四季 — 每年循环，不同季节不同内容
20	    // ============================================================
21	    {
22	      id: "spring_employment_boom",
23	      phase: "street",
24	      icon: "🌸",
25	      title: "开春招工潮",
26	      story:
27	        "春节过后，城市迎来了招工旺季。工地、工厂、餐饮店门口都贴着招工启事。街上的招工中介也比平时多了好几家——春天是找工作的好时候。",
28	      choices: [
29	        {
30	          text: "💪 趁旺季多打几份工",
31	          hint: "加班加成",
32	          cost: 0,
33	          apply: function (st) {
34	            st.resources.cash += 150 + Math.floor(Math.random() * 100);
35	            st.needs.fatigue = Math.min(100, st.needs.fatigue + 20);
36	            StateManager.addMessage(
37	              "🌸 开春招工旺季，你多打了几份工，收入不错。",
38	              "success",
39	            );
40	          },
41	        },
42	        {
43	          text: "📋 看看有没有更好的工作机会",
44	          hint: "可能找到新工作",
45	          apply: function (st) {
46	            st.flags._springJobSearch = true;
47	            StateManager.addMessage(
48	              "🌸 你留意了招工信息，似乎有更好的机会在等着你。",
49	              "hint",
50	            );
51	          },
52	        },
53	        {
54	          text: "😌 不急，慢慢来",
55	          hint: "保持体力",
56	          apply: function (st) {
57	            StateManager.addMessage(
58	              "🌸 你决定不跟风，保持自己的节奏。",
59	              "info",
60	            );
61	          },
62	        },
63	      ],
64	    },
65	    {
66	      id: "summer_heat_struggle",
67	      phase: "street",
68	      icon: "☀️",
69	      title: "炎夏难熬",
70	      story:
71	        "三伏天，太阳像火炉一样烤着街道。摆摊的商贩都躲到了阴凉处，工地的工人们也放慢了节奏。这种天气下干活，体力消耗是平时的两倍。",
72	      conditions: function (st) {
73	        return st.player.day > 60 || !st.flags._summerFlag;
74	      },
75	      choices: [
76	        {
77	          text: "💦 忍忍继续干",
78	          hint: "收入正常但疲劳翻倍",
79	          apply: function (st) {
80	            st.resources.cash += 80 + Math.floor(Math.random() * 50);
81	            st.needs.fatigue = Math.min(100, st.needs.fatigue + 30);
82	            st.needs.health = Math.max(0, st.needs.health - 3);
83	            StateManager.addMessage(
84	              "☀️ 你在酷暑中坚持工作，赚了钱但身体吃不消。",
85	              "info",
86	            );
87	          },
88	        },
89	        {
90	          text: "🧊 买冷饮消暑",
91	          hint: "花¥15减疲劳",
92	          cost: 15,
93	          apply: function (st) {
94	            st.resources.cash -= 15;
95	            st.needs.fatigue -= 10;
96	            StateManager.addMessage(
97	              "☀️ 一瓶冰水解了暑气，感觉好多了。",
98	              "success",
99	            );
100	          },
101	        },
102	        {
103	          text: "🌳 休息一天",
104	          hint: "体力恢复但没收入",
105	          apply: function (st) {
106	            st.needs.fatigue = Math.max(0, st.needs.fatigue - 25);
107	            StateManager.addMessage(
108	              "☀️ 你在树荫下歇了一天，避开了最热的时段。",
109	              "hint",
110	            );
111	          },
112	        },
113	      ],
114	    },
115	    {
116	      id: "autumn_price_drop",
117	      phase: "street",
118	      icon: "🍂",
119	      title: "秋收季节·物价波动",
120	      story:
121	        "入秋后，农产品大量上市，菜市场的水果蔬菜价格明显下降。与此同时，服装店开始上秋冬新款，旧款打折清仓。精明的商家知道这是个囤货的好时机。",
122	      choices: [
123	        {
124	          text: "🛒 趁便宜多买食材",
125	          hint: "食材开销减半",
126	          apply: function (st) {
127	            st.flags._autumnGroceries = true;
128	            st.resources.cash -= 20;
129	            StateManager.addMessage(
130	              "🍂 你囤了一批便宜食材，未来几天的吃饭开销会省不少。",
131	              "success",
132	            );
133	          },
134	        },
135	        {
136	          text: "📦 倒卖换季商品",
137	          hint: "薄利但稳妥",
138	          apply: function (st) {
139	            var profit = 40 + Math.floor(Math.random() * 50);
140	            st.resources.cash += profit;
141	            StateManager.addMessage(
142	              "🍂 你倒卖了一批换季商品，净赚¥" + profit + "。",
143	              "success",
144	            );
145	          },
146	        },
147	      ],
148	    },
149	    {
150	      id: "winter_shelter_struggle",
151	      phase: "street",
152	      icon: "❄️",
153	      title: "严冬求生",
154	      story:
155	        "寒潮来袭，气温骤降到零下。街上的流浪猫狗都不见了踪影，路面结了一层薄冰。这种天气里，有个温暖的住处比什么都重要。",
156	      choices: [
157	        {
158	          text: "🔥 找地方取暖",
159	          hint: "减少生病概率",
160	          apply: function (st) {
161	            st.needs.health = Math.min(100, (st.needs.health || 50) + 8);
162	            StateManager.addMessage(
163	              "❄️ 你在救助站取暖，身体暖和过来了。",
164	              "success",
165	            );
166	          },
167	        },
168	        {
169	          text: "💰 硬扛着去工作",
170	          hint: "高风险高回报",
171	          apply: function (st) {
172	            st.resources.cash += 120 + Math.floor(Math.random() * 60);
173	            st.needs.health = Math.max(0, (st.needs.health || 50) - 5);
174	            if (Math.random() < 0.3) {
175	              st.flags._everSick = true;
176	              StateManager.addMessage(
177	                "❄️ 你在严寒中工作了一天，但好像着凉了。",
178	                "danger",
179	              );
180	            } else {
181	              StateManager.addMessage(
182	                "❄️ 你咬牙在寒风中工作了一天，赚到了钱。",
183	                "success",
184	              );
185	            }
186	          },
187	        },
188	      ],
189	    },
190	    {
191	      id: "rainy_season_flood",
192	      phase: "street",
193	      icon: "🌧️",
194	      title: "雨季城市内涝",
195	      story:
196	        "连续几天的暴雨让城市多处积水，低洼地段的路面变成了小河。外卖和快递都延迟了，但有些生意反而好了起来。",
197	      choices: [
198	        {
199	          text: "🚣 蹚水送外卖",
200	          hint: "溢价但危险",
201	          apply: function (st) {
202	            st.resources.cash += 130 + Math.floor(Math.random() * 80);
203	            st.needs.fatigue = Math.min(100, st.needs.fatigue + 25);
204	            StateManager.addMessage(
205	              "🌧️ 你在暴雨中奋力送货，收到了不少小费！",
206	              "success",
207	            );
208	          },
209	        },
210	        {
211	          text: "🏠 待在屋里",
212	          hint: "安全但没收入",
213	          apply: function (st) {
214	            st.needs.hygiene = Math.min(100, (st.needs.hygiene || 50) + 5);
215	            StateManager.addMessage(
216	              "🌧️ 你在屋里躲了一天雨，读了一会儿书。",
217	              "hint",
218	            );
219	          },
220	        },
221	      ],
222	    },
223	
224	    // ============================================================
225	    // NPC偶遇 — 依赖好感度和位置
226	    // ============================================================
227	    {
228	      id: "npc_aunt_wang_tenant_help",
229	      phase: "street",
230	      icon: "🏠",
231	      title: "王大婶的租客纠纷",
232	      story:
233	        "王大婶皱着眉头来找你：'楼上那家租客拖欠了两个月房租，还总在半夜唱歌。你是读过书的人，帮我想想办法？'",
234	      conditions: function (st) {
235	        return (
236	          st.relationships &&
237	          st.relationships.aunt_wang &&
238	          st.relationships.aunt_wang.affinity >= 30 &&
239	          (st.housing.tier || 0) >= 1
240	        );
241	      },
242	      choices: [
243	        {
244	          text: "📝 帮王大婶写催租通知",
245	          hint: "好感+5",
246	          apply: function (st) {
247	            if (st.relationships.aunt_wang)
248	              st.relationships.aunt_wang.affinity = Math.min(
249	                100,
250	                st.relationships.aunt_wang.affinity + 5,
251	              );
252	            st.resources.cash += 20;
253	            StateManager.addMessage(
254	              "🏠 你帮王大婶写了正规催租通知，她满意地塞给你¥20。",
255	              "success",
256	            );
257	          },
258	        },
259	        {
260	          text: "🤝 上楼去调解",
261	          hint: "可能有用或碰钉子",
262	          apply: function (st) {
263	            if (Math.random() < 0.6) {
264	              if (st.relationships.aunt_wang)
265	                st.relationships.aunt_wang.affinity = Math.min(
266	                  100,
267	                  st.relationships.aunt_wang.affinity + 8,
268	                );
269	              st.resources.cash += 50;
270	              StateManager.addMessage(
271	                "🏠 你成功调解了纠纷！王大婶开心地给了你¥50感谢费。",
272	                "success",
273	              );
274	            } else {
275	              StateManager.addMessage(
276	                "🏠 租客态度恶劣，调解失败。王大婶叹了口气。",
277	                "danger",
278	              );
279	            }
280	          },
281	        },
282	      ],
283	    },
284	    {
285	      id: "npc_boss_li_side_job",
286	      phase: "street",
287	      icon: "🔨",
288	      title: "李工头的私活",
289	      story:
290	        "李工头神秘兮兮地把你拉到一边：'有个老客户的别墅要翻新院子，不经过公司，咱们自己干。两天活儿，分你¥300，干不干？'",
291	      conditions: function (st) {
292	        return (
293	          st.relationships &&
294	          st.relationships.boss_li &&
295	          st.relationships.boss_li.affinity >= 40 &&
296	          st.trade &&
297	          st.trade.currentLocation === "construction"
298	        );
299	      },
300	      choices: [
301	        {
302	          text: "💪 干！私活赚钱多",
303	          hint: "收入高但无保障",
304	          apply: function (st) {
305	            st.resources.cash += 300 + Math.floor(Math.random() * 100);
306	            st.needs.fatigue = Math.min(100, st.needs.fatigue + 25);
307	            if (Math.random() < 0.1) {
308	              st.flags._everInjured = true;
309	              StateManager.addMessage(
310	                "🔨 院子翻新出了点意外，你受了轻伤，但钱拿到了。",
311	                "danger",
312	              );
313	            } else {
314	              StateManager.addMessage(
315	                "🔨 你和李工头干了两天私活，分到了¥" +
316	                  (300 + Math.floor(Math.random() * 100)) +
317	                  "！",
318	                "success",
319	              );
320	            }
321	          },
322	        },
323	        {
324	          text: "⚠️ 算了，没保障",
325	          hint: "安全第一",
326	          apply: function (st) {
327	            if (st.relationships.boss_li)
328	              st.relationships.boss_li.affinity = Math.max(
329	                0,
330	                st.relationships.boss_li.affinity - 2,
331	              );
332	            StateManager.addMessage(
333	              "🔨 你婉拒了私活，李工头有点失望但表示理解。",
334	              "info",
335	            );
336	          },
337	        },
338	      ],
339	    },
340	    {
341	      id: "npc_sister_zhang_tip",
342	      phase: "street",
343	      icon: "💼",
344	      title: "张姐的内部消息",
345	      story:
346	        "张姐在东张西望后压低声音说：'城东新开了一家大型物流分拣中心，正在大量招人。我知道内部HR的微信，帮你推一把？不过人情费得你自己出。'",
347	      conditions: function (st) {
348	        return (
349	          st.relationships &&
350	          st.relationships.sister_zhang &&
351	          st.relationships.sister_zhang.affinity >= 35 &&
352	          st.trade &&
353	          st.trade.currentLocation === "commercialDist"
354	        );
355	      },
356	      choices: [
357	        {
358	          text: "💰 给¥50人情费",
359	          hint: "解锁高薪工作",
360	          cost: 50,
361	          apply: function (st) {
362	            st.resources.cash -= 50;
363	            st.flags._zhangLogisticsJob = true;
364	            if (st.relationships.sister_zhang)
365	              st.relationships.sister_zhang.affinity = Math.min(
366	                100,
367	                st.relationships.sister_zhang.affinity + 3,
368	              );
369	            StateManager.addMessage(
370	              "💼 张姐帮你推了简历，物流中心的HR说下周可以来面试！",
371	              "success",
372	            );
373	          },
374	        },
375	        {
376	          text: "🙏 先记着，回头再说",
377	          hint: "保留机会",
378	          apply: function (st) {
379	            st.flags._zhangOfferPending = true;
380	            StateManager.addMessage(
381	              "💼 张姐说消息给你留着，想好了随时找她。",
382	              "hint",
383	            );
384	          },
385	        },
386	      ],
387	    },
388	    {
389	      id: "npc_old_zhou_secret",
390	      phase: "street",
391	      icon: "🗑️",
392	      title: "老周的废品宝藏",
393	      story:
394	        "老周正在整理一堆旧书废纸，突然兴奋地朝你招手：'快来快来！我淘到宝了——这些旧书里有几本绝版的专业书，网上能卖好价钱！你会用手机，帮我挂上去？'",
395	      conditions: function (st) {
396	        return (
397	          st.relationships &&
398	          st.relationships.old_zhou &&
399	          st.relationships.old_zhou.affinity >= 30 &&
400	          st.trade &&
401	          st.trade.currentLocation === "slum"
402	        );
403	      },
404	      choices: [
405	        {
406	          text: "📱 帮老周挂二手平台",
407	          hint: "分你一半",
408	          apply: function (st) {
409	            var profit = 80 + Math.floor(Math.random() * 120);
410	            st.resources.cash += profit;
411	            if (st.relationships.old_zhou)
412	              st.relationships.old_zhou.affinity = Math.min(
413	                100,
414	                st.relationships.old_zhou.affinity + 4,
415	              );
416	            StateManager.addMessage(
417	              "🗑️ 绝版书卖了¥" + profit * 2 + "，老周分了你¥" + profit + "！",
418	              "success",
419	            );
420	          },
421	        },
422	        {
423	          text: "📖 先看看有没有自己有用的",
424	          hint: "可能学到技能",
425	          apply: function (st) {
426	            var skillGain = Math.floor(Math.random() * 15) + 5;
427	            for (var sk in st.skills) {
428	              st.skills[sk].xp += skillGain;
429	              break;
430	            }
431	            StateManager.addMessage(
432	              "🗑️ 你在旧书堆里找到一本有用的教材，所有技能+少量XP。",
433	              "success",
434	            );
435	          },
436	        },
437	      ],
438	    },
439	    {
440	      id: "npc_chef_chen_food_crisis",
441	      phase: "street",
442	      icon: "🍳",
443	      title: "陈师傅的食材危机",
444	      story:
445	        "陈师傅焦急地翻着手机：'今天送菜的供应商临时涨价，比平时贵了三成！不买的话今天没法开门。你知道附近哪里能买到平价食材吗？'",
446	      conditions: function (st) {
447	        return (
448	          st.relationships &&
449	          st.relationships.chef_chen &&
450	          st.relationships.chef_chen.affinity >= 30
451	        );
452	      },
453	      choices: [
454	        {
455	          text: "🛒 带他去批发市场",
456	          hint: "好感+5，奖励¥50",
457	          apply: function (st) {
458	            st.resources.cash += 50;
459	            if (st.relationships.chef_chen)
460	              st.relationships.chef_chen.affinity = Math.min(
461	                100,
462	                st.relationships.chef_chen.affinity + 5,
463	              );
464	            StateManager.addMessage(
465	              "🍳 你带陈师傅去了批发市场，省了一半钱！他开心地给了你¥50。",
466	              "success",
