483	                  st.relationships.chef_chen.affinity + 8,
484	                );
485	              st.resources.cash += 100;
486	              StateManager.addMessage(
487	                "🍳 你拿出存的食材帮陈师傅解了燃眉之急！他感动地给了¥100。",
