501	    // ============================================================
502	    // 资源危机 — 基于经济状况动态生成
503	    // ============================================================
504	    {
505	      id: "crisis_medical_bill",
506	      phase: "street",
507	      icon: "🏥",
508	      title: "突如其来的医药费",
509	      story:
510	        "你的身体发出了警报——持续的头痛和低烧让你不得不去医院。检查后发现是慢性疲劳综合症的前兆，医生开了一个疗程的药，费用¥200。",
511	      conditions: function (st) {
512	        return (st.needs.health || 50) < 35;
513	      },
514	      choices: [
515	        {
516	          text: "💊 买药治疗",
517	          hint: "健康+15，花费¥200",
518	          cost: 200,
519	          apply: function (st) {
520	            st.resources.cash -= 200;
521	            st.needs.health = Math.min(100, (st.needs.health || 50) + 15);
