525	            );
526	          },
527	        },
528	        {
529	          text: "💪 扛一扛",
530	          hint: "不花钱但可能恶化",
531	          apply: function (st) {
532	            st.needs.health = Math.max(0, (st.needs.health || 50) - 5);
533	            StateManager.addMessage(
534	              "🏥 你决定硬扛，但身体似乎更差了……",
535	              "danger",
536	            );
537	          },
538	        },
539	        {
540	          text: "☎️ 找人借钱",
