1	/**
2	 * 每日结算管线 — 声明式步骤编排
3	 *
4	 * 将 endDay 的 14 步硬编码拆为独立管线步骤，每步自声明：
5	 *   name: 唯一标识
6	 *   fn: 执行函数
7	 *   after: 依赖的前置步骤（可选）
8	 *   skipOnExtreme: 极端状态时是否跳过（默认 true）
9	 *
10	 * 架构原则：新增结算逻辑只需向 DAILY_PIPELINE 数组添加一个步骤对象，
11	 * 不需要修改 endDay 的主流程。
12	 *
13	 * MiniMax 友好：每个步骤的输入输出清晰，依赖声明显式化。
14	 */
15	
16	/** 每日结算步骤管线（按顺序执行） */
17	const DAILY_PIPELINE = [
18	  // === 基础递进 ===
19	  {
20	    name: "day_increment",
21	    fn: function (state) {
22	      state.player.day++;
23	      state.player.actionPoints = state.player.maxActionPoints;
24	      state.player.timeSlot = "morning";
25	    },
26	  },
27	
28	  // === 需求衰减 ===
29	  {
30	    name: "needs_decay",
31	    fn: function (state) {
32	      applyNeedsDecay(state);
33	    },
34	  },
35	
36	  // === 状态交叉影响 ===
37	  {
38	    name: "status_interactions",
39	    fn: function (state) {
40	      applyStatusInteractions(state);
41	    },
42	  },
43	
44	  // === 睡眠恢复 ===
45	  {
46	    name: "sleep_recovery",
47	    fn: function (state) {
48	      var house = getCurrentHousing(state);
49	      var recovery = house.fatigueRecovery;
50	      var penalty = state._fatigueRecoveryPenalty || 1.0;
51	      // 命名疾病的疲劳恢复倍率叠加（失眠症等）
52	      if (typeof getIllnessAttrDebuffs === "function") {
53	        var ad = getIllnessAttrDebuffs(state);
54	        if (ad.fatigueRecoveryMult && ad.fatigueRecoveryMult < 1) {
55	          penalty *= ad.fatigueRecoveryMult;
56	        }
57	      }
58	      if (penalty < 1.0) {
59	        StateManager.addMessage(
60	          "😢 睡眠质量很差，疲劳恢复打了" + Math.round(penalty * 100) + "%折。",
61	          "warning",
62	        );
63	      }
64	      state.needs.fatigue = Math.max(
65	        0,
66	        state.needs.fatigue - Math.round(recovery * penalty),
67	      );
68	      delete state._fatigueRecoveryPenalty;
69	      state.needs.hygiene = Math.min(
70	        100,
71	        state.needs.hygiene + (house.hygieneBonus || 0),
72	      );
73	      state.needs.happiness = Math.max(
74	        0,
75	        Math.min(100, state.needs.happiness - 3 + (house.happinessBonus || 0)),
76	      );
77	      // 王大婶好感30解锁每日带饭（饥饱+15）
78	      if (state.flags.auntWangMeal) {
79	        state.needs.hunger = Math.min(100, state.needs.hunger + 15);
80	        if (Math.random() < 0.3) {
81	          StateManager.addMessage(
82	            "🍱 早上发现门口有王大婶留的饭菜，暖心。",
83	            "info",
84	          );
85	        }
86	      }
87	    },
88	  },
89	
90	  // === 房租 ===
91	  {
92	    name: "rent",
93	    fn: function (state) {
94	      var house = getCurrentHousing(state);
95	      var selfLiving =
96	        state.investment && state.investment.selfLivePropertyId != null;
97	      if (house.rent > 0 && !selfLiving) {
98	        var rentAmount = house.rent;
99	        // 王大婶好感60解锁租房折扣（-¥50/天）
100	        if (state.flags.auntWangRentDiscount && rentAmount >= 50) {
101	          rentAmount -= 50;
102	        }
103	        if (state.resources.cash >= rentAmount) {
104	          state.resources.cash -= rentAmount;
105	          addDailyTransaction(
106	            state,
107	            "expense",
108	            "rent",
109	            rentAmount,
110	            house.name ? "房租 - " + house.name : "房租",
111	          );
112	        } else {
113	          StateManager.addMessage(
114	            "⚠️ 付不起房租 ¥" + rentAmount + "！被赶回流落街头。",
115	            "danger",
116	          );
117	          state.housing.tier = 0;
118	          state.inventory.capacity =
119	            20 + (state.housing ? state.housing.storageCapacity || 0 : 0);
120	        }
121	      }
122	      if (
123	        state.housing &&
124	        state.housing.storageRented &&
125	        state.housing.storageCapacity > 0
126	      ) {
127	        var storageRent = state.housing.storageCapacity >= 500 ? 50 : 20;
128	        if (state.resources.cash >= storageRent) {
129	          state.resources.cash -= storageRent;
130	          addDailyTransaction(
131	            state,
132	            "expense",
133	            "rent",
134	            storageRent,
135	            "仓库租金",
136	          );
137	        } else {
138	          StateManager.addMessage("⚠️ 付不起仓库租金，仓库被收回。", "danger");
139	          state.housing.storageRented = false;
140	          state.housing.storageCapacity = 0;
141	          var houseInfo =
142	            typeof getCurrentHousing === "function"
143	              ? getCurrentHousing(state)
144	              : null;
145	          var baseCap = houseInfo ? houseInfo.capacity : 20;
146	          state.inventory.capacity = baseCap;
147	        }
148	      }
149	    },
150	  },
151	
152	  // === 健康结算 ===
153	  {
154	    name: "health_tick",
155	    fn: function (state) {
156	      tickHealthStatus(state);
157	    },
158	  },
159	
160	  // === 习惯追踪 ===
161	  {
162	    name: "habit_tick",
163	    fn: function (state) {
164	      if (typeof tickHabits === "function") tickHabits(state);
165	      // 办公室工作天数追踪（职业病）
166	      if (typeof tickOfficeWorkDays === "function") tickOfficeWorkDays(state);
167	    },
168	  },
169	
170	  // === 命名疾病掷骰 ===
171	  {
172	    name: "illness_roll",
173	    fn: function (state) {
174	      if (typeof rollDailyIllness === "function") rollDailyIllness(state);
175	    },
176	  },
177	
178	  // === 疾病演化风险检查 ===
179	  {
180	    name: "illness_evolution_check",
181	    fn: function (state) {
182	      if (typeof checkEvolutionRisk === "function") checkEvolutionRisk(state);
183	    },
184	  },
185	
186	  // === 需求阈值检查 ===
187	  {
188	    name: "needs_check",
189	    fn: function (state) {
190	      checkNeedsThresholds(state);
191	    },
192	  },
193	
194	  // === 临界值延期惩罚（在 extreme_check 之前）===
195	  {
196	    name: "critical_punish",
197	    fn: function (state) {
198	      if (typeof applyDeferredCriticalPunishments === "function") {
199	        return applyDeferredCriticalPunishments(state);
200	      }
201	      return null;
202	    },
203	  },
204	
205	  // === 极端状态检测 ===
206	  {
207	    name: "extreme_check",
208	    fn: function (state) {
209	      var result = checkExtremeConditions(state);
210	      // 返回 null=正常, 'skip_day' 由调用方处理
211	      return result;
212	    },
213	  },
214	
215	  // === 情绪判定 ===
216	  {
217	    name: "emotion",
218	    fn: function (state) {
219	      determineEmotionalState(state);
220	    },
221	  },
222	
223	  // === 财务结算 ===
224	  {
225	    name: "finance",
226	    fn: function (state) {
227	      settleDailyFinance(state);
228	      // 成就追踪：现金归零
229	      if ((state.resources.cash || 0) <= 0) state.flags._everBroke = true;
230	    },
231	  },
232	
233	  // === 每日快照（用于成长图表） ===
234	  {
235	    name: "snapshot",
236	    fn: function (state) {
237	      // 1. 总资产快照
238	      if (!state.flags._cashHistory) state.flags._cashHistory = [];
239	      var totalAsset =
240	        (state.resources.cash || 0) + (state.resources.bankBalance || 0);
241	      state.flags._cashHistory.push({
242	        day: state.player.day,
243	        value: totalAsset,
244	      });
245	      if (state.flags._cashHistory.length > 90) {
246	        state.flags._cashHistory = state.flags._cashHistory.slice(-90);
247	      }
248	
249	      // 2. 收入/支出历史（供 incomeChart 使用）
250	      if (!state.history) state.history = { income: [], expense: [] };
251	      var txs = state.flags._dailyTransactions || [];
252	      var dailyIncome = 0,
253	        dailyExpense = 0;
254	      for (var ti = 0; ti < txs.length; ti++) {
255	        var t = txs[ti];
256	        if (t.type === "income") dailyIncome += t.amount || 0;
257	        else if (t.type === "expense") dailyExpense += t.amount || 0;
258	      }
259	      state.history.income.push(dailyIncome);
260	      state.history.expense.push(dailyExpense);
261	      if (state.history.income.length > 90) {
262	        state.history.income = state.history.income.slice(-90);
263	        state.history.expense = state.history.expense.slice(-90);
264	      }
