716	/** 生成每日一句话总结 */
717	function generateDailySummary(state, startCash, startHealth, startHappiness) {
718	  var cash = state.resources.cash || 0;
719	  var bank = state.resources.bankBalance || 0;
720	  var delta = cash - startCash;
721	  var healthDrop = startHealth - ((state.status && state.status.health) || 100);
722	  var happyDrop =
723	    startHappiness - ((state.needs && state.needs.happiness) || 0);
724	  var day = state.player.day || 1;
725	
726	  var highlights = [];
727	
728	  // 特殊叙事片段（优先级最高）
729	  if (state.flags._todayDeepTaskDone) {
730	    highlights.push("有个人在你心里留下了什么");
731	  } else if (state.flags._todayDebtEvent) {
732	    highlights.push("村长的钱，又压了一整天");
733	  } else if (state.flags._todayMentalEvent) {
734	    highlights.push("心里那根弦今天绷得很紧");
735	  }
736	
737	  // 财务总结（分更多档次，语气有温度）
738	  if (delta >= 1000) {
739	    highlights.push("今天是个好日子，净赚了¥" + delta.toLocaleString());
740	  } else if (delta >= 300) {
741	    highlights.push("今天赚了¥" + delta.toLocaleString() + "，还不错");
742	  } else if (delta >= 50) {
743	    highlights.push("今天净入¥" + delta.toLocaleString() + "，比昨天强点");
744	  } else if (delta >= 0) {
745	    highlights.push("今天收支基本持平，活下来了");
746	  } else if (delta < -500) {
747	    highlights.push("今天支出不少，净亏了¥" + Math.abs(delta).toLocaleString());
748	  } else if (delta < 0) {
749	    highlights.push(
750	      "今天支出略多，口袋瘦了¥" + Math.abs(delta).toLocaleString(),
751	    );
752	  }
753	
754	  // 里程碑叙事
755	  if (day === 7) highlights.push("来这座城市整整一周了");
756	  else if (day === 30) highlights.push("整整一个月，你还在");
757	  else if (day === 100) highlights.push("百天了，城市没把你打倒");
758	  else if (day === 365) highlights.push("一年了，从头到今天");
759	
760	  // 存款鼓励
761	  if (bank >= 10000 && highlights.length < 2) {
762	    highlights.push("银行里¥" + bank.toLocaleString() + "，是你在这城市的底气");
763	  } else if (bank > 0 && highlights.length < 2) {
764	    highlights.push("银行里的¥" + bank.toLocaleString() + "还在生息");
765	  }
766	
767	  // 健康/心情状态
768	  if (healthDrop >= 15) {
769	    highlights.push("身体吃不消了，明天注意");
770	  } else if (happyDrop >= 20) {
771	    highlights.push("今天过得不太开心，明天找找乐子");
772	  }
773	
774	  // 村长债务提示（仅经典模式/有 villageDebt 的剧本）
775	  if ((state.resources.villageDebt || 0) > 0 && highlights.length < 2) {
776	    highlights.push(
777	      "村长那¥" +
778	        (state.resources.villageDebt || 0).toLocaleString() +
779	        "的债还压着呢",
780	    );
781	  }
782	
783	  // 节日氛围
784	  if (typeof getCurrentFestival === "function") {
785	    var fest = getCurrentFestival(day);
786	    if (fest && highlights.length < 2)
787	      highlights.push(fest.icon + " " + fest.name + "的气氛越来越浓了");
788	  }
789	
790	  // 梦想进度
791	  if (typeof getDreamProgress === "function" && highlights.length < 2) {
792	    var dp = getDreamProgress(state);
793	    if (dp > 0 && dp < 100) highlights.push("梦想进度" + dp + "%，一直往前");
794	  }
795	
796	  // 清除今日临时标记
797	  delete state.flags._todayDeepTaskDone;
798	  delete state.flags._todayDebtEvent;
799	  delete state.flags._todayMentalEvent;
800	
801	  if (!highlights.length) highlights.push("平凡的一天，活着就是赢了");
802	
803	  var summary = highlights.slice(0, 2).join("，") + "。";
804	  return "📋 今日总结：" + summary;
805	}
806	
807	/**
808	 * 执行每日结算管线。
809	 * 遍历所有步骤，遇到极端状态('skip_day')时短路。
810	 * MiniMax 友好：新增步骤只需 push 一个 {name, fn} 对象。
811	 */
812	function runDailyPipeline(state) {
813	  // 记录日始状态用于今日总结（存入 state.flags 供 end_log fn 读取）
814	  state.flags._dayStartCash = state.resources.cash || 0;
815	  state.flags._dayStartHealth = (state.status && state.status.health) || 100;
816	  state.flags._dayStartHappiness = (state.needs && state.needs.happiness) || 0;
817	
818	  for (var i = 0; i < DAILY_PIPELINE.length; i++) {
819	    var step = DAILY_PIPELINE[i];
820	
821	    // 极端状态短路逻辑：
822	    // extreme_check / critical_punish 返回 'skip_day' 时，跳过后续非核心步骤
823	    // 但 finance / autosave 始终执行（保证利息和存档不丢）
824	    if (step.name === "extreme_check" || step.name === "critical_punish") {
825	      var result = step.fn(state);
826	      if (result === "skip_day") {
827	        StateManager.addMessage(
828	          "🌙 第" + state.player.day + "天在昏迷中过去了...",
829	          "danger",
830	        );
831	        // 执行最后的核心步骤：财务、存档
832	        for (var j = i + 1; j < DAILY_PIPELINE.length; j++) {
833	          var lateStep = DAILY_PIPELINE[j];
834	          if (lateStep.name === "finance" || lateStep.name === "autosave") {
835	            lateStep.fn(state);
836	          }
837	        }
838	        return; // 短路
839	      }
840	    } else {
841	      step.fn(state);
842	    }
843	  }
844	}
845	
846	/**
847	 * endDay — 仅保留管线调度逻辑（MiniMax 友好：170行→8行）
848	 */
849	function endDay() {
850	  var state = StateManager.getState();
851	  runDailyPipeline(state);
852	}
