1	/**
2	 * Illness 系统 — 长期不良习惯 → 命名疾病
3	 *
4	 * 三大循环：
5	 *   1. 每日 tickHabits(state) — 根据当日 needs 更新各种 streak/counter。
6	 *   2. 每日 rollDailyIllness(state) — 检查 habit 阈值，按 severity 决定的概率患病。
7	 *   3. 每日 tickIllnessDecay(state) — 已患疾病按 naturalCureDays 自然恢复。
8	 *
9	 * 症状叠加：
10	 *   - getIllnessStatusMods(state) — 返回 {health, hunger, fatigue, ...} 累加值
11	 *   - 由 applyStatusInteractions 调用，叠加到 needs 上
12	 *   - getIllnessAttrDebuffs(state) — 返回 {physiqueDebuff, mentalDebuff, ...}
13	 *   - 由 getEffectiveStats 调用，进一步打折
14	 *
15	 * 治疗：
16	 *   - openClinicModal() 在医院解锁的"看病"行动里调起
17	 *   - 选病种 + 选档次（药店便宜慢 / 医院贵快）
18	 */
19	
20	// ====== 每日习惯追踪 ======
21	
22	/** 每日结算时调用：更新 streak/counter */
23	function tickHabits(state) {
24	  var n = state.needs;
25	  state.flags._habits = state.flags._habits || {
26	    junkFoodMeals: 0,
27	    lowHungerStreak: 0,
28	    lowHygieneStreak: 0,
29	    lowHappinessStreak: 0,
30	    highFatigueStreak: 0,
31	    lateNightActions: 0,
32	    stomach_inflammationCount: 0,
33	    // 疾病演化追踪：每种病治愈/痊愈的次数
34	    gastritisCount: 0,
35	    depressionCount: 0,
36	    coldCount: 0,
37	    pneumoniaCount: 0,
38	    malnutritionCount: 0,
39	    insomniaCount: 0,
40	    overworkCount: 0,
41	    // 特殊习惯
42	    officeWorkDays: 0,
43	    hungerHighStreak: 0,
44	    healthUnder30: 0,
45	  };
46	  var h = state.flags._habits;
47	
48	  // 连续低 hunger
49	  if (n.hunger < 25) h.lowHungerStreak = (h.lowHungerStreak || 0) + 1;
50	  else h.lowHungerStreak = 0;
51	
52	  // 连续低 hygiene
53	  if (n.hygiene < 30) h.lowHygieneStreak = (h.lowHygieneStreak || 0) + 1;
54	  else h.lowHygieneStreak = 0;
55	
56	  // 连续低 happiness
57	  if (n.happiness < 20) h.lowHappinessStreak = (h.lowHappinessStreak || 0) + 1;
58	  else h.lowHappinessStreak = 0;
59	
60	  // 连续高 fatigue
61	  if (n.fatigue > 80) h.highFatigueStreak = (h.highFatigueStreak || 0) + 1;
62	  else h.highFatigueStreak = 0;
63	
64	  // 连续高 hunger（肥胖风险）
65	  if (n.hunger > 80) h.hungerHighStreak = (h.hungerHighStreak || 0) + 1;
66	  else h.hungerHighStreak = 0;
67	
68	  // 健康<30 天数
69	  if (state.status && state.status.health < 30)
70	    h.healthUnder30 = (h.healthUnder30 || 0) + 1;
71	  else h.healthUnder30 = 0;
72	
73	  // 办公室工作天数（由外部调用累加）
74	  // tickOfficeWorkDays 在 daily_pipeline 中调用
75	
76	  // 疾病演化计数：已痊愈的疾病计入历史
77	  // 在 tickIllnessDecay 中，当疾病自然康复时调用 recordIllnessCure
78	}
79	
80	// ====== 每日患病判定 ======
81	
82	/** 检查所有疾病的触发条件，按概率患病 */
83	function rollDailyIllness(state) {
84	  if (!ILLNESSES) return;
85	  state.flags._habits = state.flags._habits || {};
86	  var h = state.flags._habits;
87	
88	  for (var key in ILLNESSES) {
89	    if (!ILLNESSES.hasOwnProperty(key)) continue;
90	    var ill = ILLNESSES[key];
91	    if (!ill.triggerHabit) continue;
92	
93	    // 已有该病则跳过
94	    if (hasIllness(state, key)) continue;
95	
96	    // 检查 triggerHabit 所有条件
97	    var conditionsMet = true;
98	    var habitName = null;
99	    for (var hk in ill.triggerHabit) {
100	      if (!ill.triggerHabit.hasOwnProperty(hk)) continue;
101	      var threshold = ill.triggerHabit[hk];
102	      var actual;
103	      if (hk === "age") actual = state.player.age || 20;
104	      else actual = h[hk] || 0;
105	      if (actual < threshold) {
106	        conditionsMet = false;
107	        break;
108	      }
109	      if (!habitName) habitName = hk;
110	    }
111	    if (!conditionsMet) continue;
112	
113	    // 概率掷骰
114	    var ch = ill.triggerChance || 0.5;
115	    if (Math.random() >= ch) continue;
116	
117	    // 患病！
118	    _addIllness(state, key);
119	    state.flags._everGotSick = true; // 成就追踪
120	
121	    // 部分清零相关 habit（避免立刻再得一次）
122	    if (habitName === "lowHungerStreak")
123	      h.lowHungerStreak = Math.floor(h.lowHungerStreak / 2);
124	    else if (habitName === "lowHygieneStreak")
125	      h.lowHygieneStreak = Math.floor(h.lowHygieneStreak / 2);
126	    else if (habitName === "lowHappinessStreak")
127	      h.lowHappinessStreak = Math.floor(h.lowHappinessStreak / 2);
128	    else if (habitName === "highFatigueStreak")
129	      h.highFatigueStreak = Math.floor(h.highFatigueStreak / 2);
130	    else if (habitName === "junkFoodMeals")
131	      h.junkFoodMeals = Math.max(0, h.junkFoodMeals - 5);
132	    else if (habitName === "lateNightActions")
133	      h.lateNightActions = Math.max(0, h.lateNightActions - 4);
134	  }
135	}
136	
137	function _addIllness(state, illnessId) {
138	  var ill = ILLNESSES[illnessId];
139	  if (!ill) return;
140	  state.status.illnesses = state.status.illnesses || [];
141	  state.status.illnesses.push({
142	    id: illnessId,
143	    contractedDay: state.player.day,
144	    severity: ill.severity || 1,
145	    treated: false,
146	  });
147	  // 兼容旧字段（让现有代码能继续读 sick）
148	  state.status.sick = true;
149	
150	  var msg = (ill.icon || "🤒") + " 你患上了" + ill.name + "！";
151	  if (ill.isEvolution) {
152	    msg += "（由既往疾病演化而来）";
153	  }
154	  if (ill.isCritical) {
155	    msg += " ⚠️ 危急重症！";
156	  }
157	  msg += " " + (ill.desc || "");
158	
159	  StateManager.addMessage(msg, "danger");
160	
161	  // 追踪病史计数（用于演化链）- 患病时计数
162	  state.flags._habits = state.flags._habits || {};
163	  var evolutionCountMap = {
164	    cold: "coldCount",
165	    stomach_inflammation: "stomach_inflammationCount",
166	    gastritis: "gastritisCount",
167	    depression: "depressionCount",
168	    pneumonia: "pneumoniaCount",
169	    malnutrition: "malnutritionCount",
170	    insomnia: "insomniaCount",
171	    overwork: "overworkCount",
172	  };
173	  if (evolutionCountMap[illnessId]) {
174	    var countKey = evolutionCountMap[illnessId];
175	    state.flags._habits[countKey] = (state.flags._habits[countKey] || 0) + 1;
176	  }
177	}
178	
179	/** 记录疾病痊愈（用于演化链追踪） */
180	function recordIllnessCure(state, illnessId) {
181	  var ill = ILLNESSES[illnessId];
182	  if (!ill) return;
183	  var h = (state.flags._habits = state.flags._habits || {});
184	
185	  // 将痊愈的疾病计入演化历史
186	  if (illnessId === "cold") h.coldCount = (h.coldCount || 0) + 1;
187	  else if (illnessId === "stomach_inflammation")
188	    h.stomach_inflammationCount = (h.stomach_inflammationCount || 0) + 1;
189	  else if (illnessId === "gastritis")
190	    h.gastritisCount = (h.gastritisCount || 0) + 1;
191	  else if (illnessId === "depression")
192	    h.depressionCount = (h.depressionCount || 0) + 1;
193	  else if (illnessId === "pneumonia")
194	    h.pneumoniaCount = (h.pneumoniaCount || 0) + 1;
195	  else if (illnessId === "malnutrition")
196	    h.malnutritionCount = (h.malnutritionCount || 0) + 1;
197	  else if (illnessId === "insomnia")
198	    h.insomniaCount = (h.insomniaCount || 0) + 1;
199	  else if (illnessId === "overwork")
200	    h.overworkCount = (h.overworkCount || 0) + 1;
201	}
202	
203	// ====== 每日疾病结算 ======
204	
205	/** 每日：自然恢复 / 慢性病按月扣费 / 累计症状副作用 */
206	function tickIllnessDecay(state) {
207	  if (!state.status.illnesses) state.status.illnesses = [];
208	  var remaining = [];
209	  for (var i = 0; i < state.status.illnesses.length; i++) {
210	    var inst = state.status.illnesses[i];
211	    var ill = ILLNESSES[inst.id];
212	    if (!ill) continue;
213	
214	    // 慢性病不会自然好（hypertension）
215	    if (ill.isChronic) {
216	      _tickChronic(state, inst, ill);
217	      remaining.push(inst);
218	      continue;
219	    }
220	
221	    // 已治疗：加速康复
222	    var daysSince = state.player.day - inst.contractedDay;
223	    var minDays =
224	      ill.naturalCureDays && ill.naturalCureDays[0]
225	        ? ill.naturalCureDays[0]
226	        : 5;
227	    var maxDays =
228	      ill.naturalCureDays && ill.naturalCureDays[1]
229	        ? ill.naturalCureDays[1]
230	        : 8;
231	    if (inst.treated) {
232	      // 治疗后康复时间减半
233	      minDays = Math.ceil(minDays / 2);
234	      maxDays = Math.ceil(maxDays / 2);
235	    }
236	
237	    // 营养不良需要 nutritious 餐才能康复
238	    if (ill.requiresNutrition && !inst.treated) {
239	      var recentNutrition =
240	        (state.flags._habits && state.flags._habits.junkFoodMeals) || 0;
241	      if (recentNutrition >= 3) {
242	        // 还在吃垃圾食品，不康复
243	        remaining.push(inst);
244	        continue;
245	      }
246	    }
247	
248	    // 累计症状（health 持续掉、需要的 needs 加成）
249	    if (ill.symptom) {
250	      if (ill.symptom.health) {
251	        state.status.health = Math.max(
252	          0,
253	          state.status.health + ill.symptom.health,
254	        );
255	      }
256	      // 随机晕厥（高血压）
257	      if (
258	        ill.symptom.randomFaintCh &&
259	        Math.random() < ill.symptom.randomFaintCh
260	      ) {
261	        state.needs.fatigue = Math.min(100, state.needs.fatigue + 20);
262	        StateManager.addMessage(
263	          "💢 " + ill.name + "突发，你眩晕了一下。",
264	          "warning",
265	        );
266	      }
267	
268	      // 随机吐血（胃癌）
269	      if (
270	        ill.symptom.randomVomitCh &&
271	        Math.random() < ill.symptom.randomVomitCh
272	      ) {
273	        state.status.health = Math.max(0, state.status.health - 3);
274	        StateManager.addMessage(
275	          "🩸 " + ill.name + "发作，你吐了血，健康-3！",
276	          "danger",
277	        );
278	      }
279	
280	      // 幻觉（重度失眠）
281	      if (
282	        ill.symptom.hallucinationCh &&
283	        Math.random() < ill.symptom.hallucinationCh
284	      ) {
285	        StateManager.addMessage(
286	          "👻 " + ill.name + "让你产生了幻觉，精神恍惚。",
287	          "warning",
288	        );
289	      }
290	
291	      // 猝死风险检测
292	      if (
293	        ill.symptom.dailyDeathChance &&
294	        Math.random() < ill.symptom.dailyDeathChance
295	      ) {
296	        StateManager.addMessage(
297	          "💔 " + ill.name + "导致猝死！你的心脏停止了跳动。",
298	          "danger",
299	        );
300	        state.player.alive = false;
301	        state.status.health = 0;
302	        // 游戏结束处理由外部接管
303	        continue;
304	      }
305	
306	      // 头晕（贫血）
307	      if (ill.symptom.dizzinessCh && Math.random() < ill.symptom.dizzinessCh) {
308	        state.needs.fatigue += 5;
309	        StateManager.addMessage(
310	          "😵 " + ill.name + "让你头晕目眩，疲劳+5。",
311	          "warning",
312	        );
313	      }
314	    }
315	
316	    // 自然康复判定
317	    if (daysSince >= minDays) {
318	      var cureChance = (daysSince - minDays + 1) / (maxDays - minDays + 1);
319	      if (Math.random() < cureChance) {
320	        StateManager.addMessage(
321	          (ill.icon || "🤒") + " 你的" + ill.name + "好了。",
322	          "success",
323	        );
324	        // 记录痊愈，用于演化链追踪
325	        recordIllnessCure(state, inst.id);
326	        continue; // 不放回 remaining
327	      }
328	    }
329	    remaining.push(inst);
330	  }
331	  state.status.illnesses = remaining;
332	
333	  // 派生兼容字段
334	  state.status.sick = state.status.illnesses.length > 0;
335	}
336	
337	function _tickChronic(state, inst, ill) {
338	  // 慢性病按月（30天）扣费；不交则发作
339	  var lastPaid = state.flags._chronicMonthlyPaid || inst.contractedDay;
340	  var due = state.player.day - lastPaid >= 30;
341	  if (due) {
342	    var monthly =
343	      (typeof ill.treatCostMonthly === "number" && ill.treatCostMonthly) ||
344	      (ill.treatCost && ill.treatCost.hospital_monthly) ||
345	      200;
346	    if (state.resources.cash >= monthly) {
347	      state.resources.cash -= monthly;
348	      state.flags._chronicMonthlyPaid = state.player.day;
349	      if (typeof addDailyTransaction === "function") {
350	        addDailyTransaction(
351	          state,
352	          "expense",
353	          "medical",
354	          monthly,
355	          ill.name + "月费",
356	        );
357	      }
358	      StateManager.addMessage(
359	        "💊 " + ill.name + "月费 ¥" + monthly + " 已自动扣除。",
360	        "info",
361	      );
362	    } else {
363	      // 没钱→症状加重
364	      state.status.health = Math.max(0, state.status.health - 5);
365	      StateManager.addMessage(
366	        "⚠️ 没钱付" + ill.name + "月费，症状加重，健康-5！",
367	        "danger",
368	      );
369	    }
370	  }
371	}
372	
373	// ====== 症状对外接口（给 interactions.js 调用）======
374	
375	/** 累计所有疾病症状对 needs/health 的每日影响（applyStatusInteractions 调用） */
376	function getIllnessNeedsImpact(state) {
377	  var impact = { hunger: 0, fatigue: 0, hygiene: 0, happiness: 0, health: 0 };
378	  if (!state.status.illnesses) return impact;
379	  for (var i = 0; i < state.status.illnesses.length; i++) {
380	    var ill = ILLNESSES[state.status.illnesses[i].id];
381	    if (!ill || !ill.symptom) continue;
382	    if (ill.symptom.hunger) impact.hunger += ill.symptom.hunger;
383	    if (ill.symptom.fatigue) impact.fatigue += ill.symptom.fatigue;
384	    if (ill.symptom.hygiene) impact.hygiene += ill.symptom.hygiene;
385	    if (ill.symptom.happiness) impact.happiness += ill.symptom.happiness;
386	    if (ill.symptom.health) impact.health += ill.symptom.health;
387	  }
388	  return impact;
389	}
390	
391	/** 累计所有疾病对有效属性的扣减（getEffectiveStats 调用） */
392	function getIllnessAttrDebuffs(state) {
393	  var d = {
394	    physique: 0,
395	    intelligence: 0,
396	    agility: 0,
397	    mental: 0,
398	    apMult: 0,
399	    fatigueRecoveryMult: 1.0,
400	  };
401	  if (!state.status.illnesses) return d;
402	  for (var i = 0; i < state.status.illnesses.length; i++) {
403	    var ill = ILLNESSES[state.status.illnesses[i].id];
404	    if (!ill || !ill.symptom) continue;
405	    if (ill.symptom.physiqueDebuff) d.physique += ill.symptom.physiqueDebuff;
406	    if (ill.symptom.intelligenceDebuff)
407	      d.intelligence += ill.symptom.intelligenceDebuff;
408	    if (ill.symptom.agilityDebuff) d.agility += ill.symptom.agilityDebuff;
409	    if (ill.symptom.mentalDebuff) d.mental += ill.symptom.mentalDebuff;
410	    if (ill.symptom.apMult) d.apMult += ill.symptom.apMult;
411	    if (ill.symptom.fatigueRecoveryMult)
412	      d.fatigueRecoveryMult *= ill.symptom.fatigueRecoveryMult;
413	  }
414	  return d;
415	}
416	
417	/** 每日累加办公室工作天数（由 daily_pipeline 调用） */
418	function tickOfficeWorkDays(state) {
419	  if (state.corporate && state.corporate.company) {
420	    var jobDef = getJobById && getJobById(state.corporate.jobId);
421	    if (jobDef && (jobDef.type === "office" || jobDef.type === "corp")) {
422	      state.flags._habits = state.flags._habits || {};
423	      state.flags._habits.officeWorkDays =
424	        (state.flags._habits.officeWorkDays || 0) + 1;
425	    }
426	  }
427	}
428	
429	// ====== 治疗 UI ======
430	
431	/** 打开诊所 / 看病弹窗（在医院解锁的行动里调用） */
432	function openClinicModal() {
433	  var state = StateManager.getState();
434	  var illnesses = state.status.illnesses || [];
435	  if (illnesses.length === 0) {
436	    showModal({
437	      title: "🏥 医院",
438	      body: '<p style="font-size:13px;line-height:1.7;">医生说：你目前没有患病，注意保持健康习惯就好。</p>',
439	      buttons: [{ text: "好的", cls: "btn-primary" }],
440	    });
441	    return;
442	  }
