571	/** 检查疾病演化风险（每日结算时调用） */
572	function checkEvolutionRisk(state) {
573	  if (!ILLNESSES || !state.status || !state.status.illnesses) return;
574	  var illnesses = state.status.illnesses;
575	  var warnedEvolution = state.flags._evolutionWarningShown || {};
576	
577	  for (var i = 0; i < illnesses.length; i++) {
578	    var inst = illnesses[i];
579	    var ill = ILLNESSES[inst.id];
580	    if (!ill || !ill.evolvesTo || ill.evolvesTo.length === 0) continue;
581	
582	    // 检查演化条件是否接近满足
583	    var h = state.flags._habits || {};
584	    for (var ei = 0; ei < ill.evolvesTo.length; ei++) {
585	      var targetId = ill.evolvesTo[ei];
586	      var targetIll = ILLNESSES[targetId];
587	      if (!targetIll || !targetIll.triggerHabit) continue;
588	
589	      // 检查每个触发条件
590	      var riskLevel = 0; // 0=无风险, 1=低风险, 2=中风险, 3=高风险
591	      var maxThreshold = 0;
592	      var closestHabit = null;
593	
594	      for (var hk in targetIll.triggerHabit) {
595	        if (!targetIll.triggerHabit.hasOwnProperty(hk)) continue;
596	        var threshold = targetIll.triggerHabit[hk];
597	        var actual = h[hk] || 0;
598	        if (hk === "age") actual = state.player.age || 20;
599	
600	        maxThreshold = Math.max(maxThreshold, threshold);
601	        var ratio = actual / threshold;
602	
603	        if (ratio >= 0.7) riskLevel = Math.max(riskLevel, 3);
604	        else if (ratio >= 0.5) riskLevel = Math.max(riskLevel, 2);
605	        else if (ratio >= 0.3) riskLevel = Math.max(riskLevel, 1);
606	
607	        if (ratio >= 0.3 && (!closestHabit || ratio > closestHabit.ratio)) {
608	          closestHabit = {
609	            habit: hk,
610	            actual: actual,
611	            threshold: threshold,
612	            ratio: ratio,
613	          };
614	        }
615	      }
616	
617	      // 只显示高风险提示（避免刷屏）
618	      if (riskLevel >= 2 && !warnedEvolution[inst.id + "_" + targetId]) {
619	        warnedEvolution[inst.id + "_" + targetId] = true;
620	        state.flags._evolutionWarningShown = warnedEvolution;
621	
622	        var riskLabel = riskLevel === 3 ? "🚨 高危" : "⚠️ 中危";
623	        var habitLabel =
624	          {
625	            junkFoodMeals: "垃圾食品",
626	            lowHungerStreak: "长期饥饿",
627	            lowHygieneStreak: "卫生极差",
628	            lowHappinessStreak: "心情低落",
629	            highFatigueStreak: "过度疲劳",
630	            lateNightActions: "夜生活",
631	            stomach_inflammationCount: "肠胃炎",
632	            coldCount: "感冒",
633	            pneumoniaCount: "肺炎",
634	            malnutritionCount: "营养不良",
635	            insomniaCount: "失眠",
636	            depressionCount: "抑郁",
637	            officeWorkDays: "办公室工作",
638	            hungerHighStreak: "过度饱食",
639	            healthUnder30: "健康低下",
640	            age: "年龄",
641	          }[closestHabit?.habit || "unknown"] ||
642	          closestHabit?.habit ||
643	          "未知习惯";
644	
645	        var msg =
646	          riskLabel +
647	          "：你的" +
648	          ill.name +
649	          "有演化成" +
650	          targetIll.name +
651	          "的风险！" +
652	          "当前" +
653	          habitLabel +
654	          "（" +
655	          closestHabit.actual +
656	          "/" +
657	          closestHabit.threshold +
658	          "）接近阈值。" +
659	          "建议尽快治疗！";
660	
661	        StateManager.addMessage(msg, riskLevel === 3 ? "danger" : "warning");
662	
663	        // 首次高危演化风险时弹出提示弹窗
664	        if (riskLevel === 3 && !state.flags._evolutionModalShown) {
665	          state.flags._evolutionModalShown = {};
666	          _showEvolutionWarningModal(state, ill, targetIll, closestHabit);
667	        }
668	      }
669	    }
670	  }
