757	/** 获取疾病演化链（用于百科展示） */
758	function getEvolutionChain(illnessId) {
759	  if (!ILLNESSES || !ILLNESSES[illnessId]) return null;
760	  var ill = ILLNESSES[illnessId];
761	  var chain = { current: ill, evolvesFrom: [], evolvesTo: [] };
762	
763	  // 追溯演化来源
