765	    for (var i = 0; i < ill.evolvesFrom.length; i++) {
766	      var fromId = ill.evolvesFrom[i];
767	      var fromIll = ILLNESSES[fromId];
768	      if (fromIll) {
769	        chain.evolvesFrom.push({
770	          id: fromIll.id,
771	          name: fromIll.name,
772	          icon: fromIll.icon,
773	          severity: fromIll.severity,
774	        });
775	      }
776	    }
777	  }
778	
779	  // 前瞻演化目标
780	  if (ill.evolvesTo) {
781	    for (var j = 0; j < ill.evolvesTo.length; j++) {
782	      var toId = ill.evolvesTo[j];
783	      var toIll = ILLNESSES[toId];
784	      if (toIll) {
785	        chain.evolvesTo.push({
786	          id: toIll.id,
787	          name: toIll.name,
788	          icon: toIll.icon,
789	          severity: toIll.severity,
790	        });
791	      }
792	    }
793	  }
794	
795	  return chain;
796	}
